class Solution {
  public int maximumLength(int[] nums) {
    int even = 0, odd = 0, alternating = 0, last = -1;
    for (int x : nums) {
      if ((x & 1) == 0) even++;
      else odd++;
      if (last < 0 || ((last ^ x) & 1) != 0) {
        alternating++;
        last = x;
      }
    }
    return Math.max(Math.max(even, odd), alternating);
  }
}
